-- Ejecutar en el SQL Editor de Supabase, DESPUES de supabase/marca-modelo-auto.sql.
-- GENERADO por scripts/match-modelos-auto.mjs (matching por palabras clave
-- sobre las descripciones reales de articulos).
--
-- v2 (2026-08-11): el cliente detecto que el filtro "Chevrolet > Onix" no
-- traia nada pese a que el catalogo tiene cientos de articulos de Onix. La
-- causa: el catalogo abrevia Chevrolet como "CHEV." (sin nunca escribir
-- "Chevrolet" completo la mayoria de las veces), y esa abreviatura no
-- estaba en la lista de alias de marca — el articulo nunca se reconocia
-- como Chevrolet y caia en Universal. Mismo problema con Peugeot ("PEUG.",
-- "PEU."), Citroen ("CITR.") y Renault ("REN."), encontrado revisando
-- sistematicamente el resto de las marcas antes de asumir que Chevrolet
-- era el unico caso. Tambien se corrigio que un articulo compatible con
-- VARIOS modelos de una misma marca a la vez (ej. "CHEV. ONIX/PRISMA/
-- COBALT/SPIN") solo quedaba taggeado con uno; ahora se taggean todos los
-- que aparecen en el texto.
--
-- Si ya se habia corrido una version anterior de este archivo, este bloque
-- borra el "Universal / Generico" que le haya quedado pegado a un articulo
-- que en esta corrida SI matcheo una marca real. Es un no-op inofensivo la
-- primera vez que se corre.
delete from public.articulos_modelos_auto amu
using public.articulos a, public.modelos_auto mo, public.marcas_auto ma
where amu.id_articulo = a.id
  and amu.id_modelo_auto = mo.id
  and mo.id_marca_auto = ma.id
  and ma.descripcion = 'Universal'
  and a.codigo in (
  ('10044'),
  ('10074'),
  ('10075'),
  ('10076'),
  ('10077'),
  ('10078'),
